The TODO comment about freeing textures when anime4k UL is not used anymore should be addressed. Looking at the codebase, similar resources like FSR's tmpOutput and NIS's nisScalerImage/nisUsmImage are allocated once and reused but are not explicitly freed when the filter changes. However, unlike those resources which have relatively fixed sizes, the anime4k UL buffers allocate a significant amount of VRAM (21 textures total) and their size depends on the input resolution. Consider implementing proper cleanup when the filter is switched away from anime4k to avoid holding onto this large memory allocation unnecessarily.
```suggestion
static void free_anime4k_ul_buffers()
{
    for (int layer = 0; layer < 7; layer++)
    {
        for (int tex = 0; tex < 3; tex++)
        {
            if (g_output.anime4kULLayers[layer][tex] != nullptr)
            {
                delete g_output.anime4kULLayers[layer][tex];
                g_output.anime4kULLayers[layer][tex] = nullptr;
            }
        }
    }

    for (int tex = 0; tex < 3; tex++)
    {
        if (g_output.anime4kULLast[tex] != nullptr)
        {
            delete g_output.anime4kULLast[tex];
            g_output.anime4kULLast[tex] = nullptr;
        }
    }

    if (g_output.anime4kULOut != nullptr)
    {
        delete g_output.anime4kULOut;
        g_output.anime4kULOut = nullptr;
    }
}

static void update_anime4k_ul_buffers(uint32_t width, uint32_t height, uint32_t outWidth, uint32_t outHeight)
{
    // Reuse existing buffers if input and output sizes already match
    if (g_output.anime4kULLayers[0][0] != nullptr
        && g_output.anime4kULLayers[0][0]->width() == width
        && g_output.anime4kULLayers[0][0]->height() == height
        && g_output.anime4kULOut != nullptr
        && g_output.anime4kULOut->width() == outWidth
        && g_output.anime4kULOut->height() == outHeight)
    {
        return;
    }

    // Free any existing buffers before reallocating at a new size
    if (g_output.anime4kULLayers[0][0] != nullptr
        || g_output.anime4kULLast[0] != nullptr
        || g_output.anime4kULOut != nullptr)
    {
        free_anime4k_ul_buffers();
    }

    CVulkanTexture::createFlags createFlags;
    createFlags.bSampled = true;
    createFlags.bStorage = true;

    // Allocate intermediate layers
    for (int layer = 0; layer < 7; layer++)
    {
        for (int tex = 0; tex < 3; tex++)
        {
            g_output.anime4kULLayers[layer][tex] = new CVulkanTexture();
            if (!g_output.anime4kULLayers[layer][tex]->BInit(width, height, 1u, DRM_FORMAT_ABGR16161616F, createFlags, nullptr))
            {
                vk_log.errorf("failed to create anime4k UL layer[%d][%d] buffer", layer, tex);
                free_anime4k_ul_buffers();
                return;
            }
        }
    }

    // Allocate last-pass buffers
    for (int tex = 0; tex < 3; tex++)
    {
        g_output.anime4kULLast[tex] = new CVulkanTexture();
        if (!g_output.anime4kULLast[tex]->BInit(width, height, 1u, DRM_FORMAT_ABGR16161616F, createFlags, nullptr))
        {
            vk_log.errorf("failed to create anime4k UL last[%d] buffer", tex);
            free_anime4k_ul_buffers();
            return;
        }
    }

    // Allocate output buffer
    g_output.anime4kULOut = new CVulkanTexture();
    if (!g_output.anime4kULOut->BInit(outWidth, outHeight, 1u, DRM_FORMAT_ARGB8888, createFlags, nullptr))
    {
        vk_log.errorf("failed to create anime4k UL output buffer");
        free_anime4k_ul_buffers();
```

